// ===== CONFIGURACIÓN DE COLAIRE (edita solo este bloque) =====
const CONFIG = {
  // Clave de Google AI Studio: https://aistudio.google.com/apikey
  GEMINI_API_KEY: 'PEGA_AQUI_TU_CLAVE_DE_GEMINI',
  GEMINI_MODEL: 'gemini-2.5-flash',
  // Bot de Telegram creado con @BotFather (déjalo vacío para no enviar alertas)
  TELEGRAM_BOT_TOKEN: '',
  // chat_id del grupo "Sala de crisis" y, si quieres, uno por entidad
  TELEGRAM_CHATS: {
    default: '',
    salud: '', bomberos: '', riesgo: '', alcaldia: '', gobernacion: '',
    cruzroja: '', defensacivil: '', movilidad: '', policia: ''
  },
};
// ===============================================================
const body = $input.first().json.body || $input.first().json;
const p = {
  texto: String(body.texto || '').slice(0, 1200),
  autor: body.autor || 'anonimo', nombre: body.nombre || body.autor || 'Ciudadano', rol: body.rol || 'ciudadano',
  ts: body.ts || Date.now(), barrioPerfil: body.barrioPerfil || null,
  local: body.local || { clas: null, candidatos: [] },
};
return [{ json: { config: CONFIG, p, t0: Date.now() } }];

const { p, config } = $input.first().json;
const prompt = `Eres el motor de interpretación de ColAIre, plataforma de participación ciudadana en Cali (Colombia) tras el sismo del 10 de agosto de 2026.
Analiza el mensaje de un ciudadano y responde SOLO con JSON válido con esta forma:
{"tipo":"emergencia|ayuda|oferta|info|charla","urgencia":"rojo|naranja|amarillo|azul|ninguna","categoria":"atrapados|heridos|colapso|estructura|incendio|gas|electrico|necesidades|via|info|null","items":[],"personal":false,"vias":[{"tipo":"calle|carrera|avenida|diagonal|transversal","numero":5,"letra":"","norte":false}],"lugar":null,"resumen":""}
Reglas:
- emergencia = riesgo para personas o estructuras (atrapados, heridos, colapso, incendio, gas, cables, grietas). rojo = vida en riesgo; naranja = daño grave.
- ayuda = se necesitan insumos o personal. oferta = alguien ofrece ayuda. info = vías bloqueadas o información útil. charla = conversación sin incidente (urgencia "ninguna").
- items solo de esta lista: Agua, Alimentos, Cobijas y ropa, Insumos para bebés, Insumos médicos, Albergue, Energía y logística, Mascotas, Aseo personal, Rescate y escombros, Voluntarios, Personal de salud, Apoyo psicológico, Evaluación estructural. personal=true si se piden personas (voluntarios, médicos, psicólogos, ingenieros).
- En Cali "la Quinta" es la Calle 5, "la Pasoancho" la Calle 13, "la Sexta" la Avenida 6 Norte, "la Roosevelt" la Calle 6. Máximo 2 vías.
- lugar = barrio o sitio conocido mencionado (ej. "Mariano Ramos", "Hospital Universitario del Valle"), o null.
- resumen: máximo 12 palabras, en español.
Mensaje: «${p.texto}»`;
return [{ json: { ...$input.first().json, geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { temperature: 0.1, responseMimeType: 'application/json' } } } }];

const prev = $('Preparar prompt').first().json;
const { p } = prev;
const g = $input.first().json;
let ia = null, error = null;
try {
  const txt = g.candidates[0].content.parts.map(x => x.text || '').join('');
  ia = JSON.parse(txt.replace(/^```json|```$/g, '').trim());
} catch (e) { error = (g.error && (g.error.message || JSON.stringify(g.error))) || String(e); }
const local = p.local.clas || {};
const TIPOS = ['emergencia','ayuda','oferta','info','charla'], URG = ['rojo','naranja','amarillo','azul','ninguna'];
const clas = {
  tipo: ia && TIPOS.includes(ia.tipo) ? ia.tipo : (local.tipo || 'charla'),
  urgencia: ia && URG.includes(ia.urgencia) ? ia.urgencia : (local.urgencia || 'ninguna'),
  categoria: ia && ia.categoria && ia.categoria !== 'null' ? ia.categoria : (local.categoria || null),
  items: ia && Array.isArray(ia.items) ? ia.items : (local.items || []),
  personal: ia ? !!ia.personal : !!local.personal,
  resumen: ia && ia.resumen ? ia.resumen : '',
  lugar: ia && ia.lugar ? ia.lugar : null,
  vias: ia && Array.isArray(ia.vias) ? ia.vias.slice(0, 2) : [],
  fuenteIA: ia ? 'gemini' : 'reglas locales',
  errorIA: error,
};
// Consulta de cruce de vías para Overpass (OpenStreetMap)
const T = { calle: '(Avenida |Av[.]? )?(Calle|Cl[.]?)', diagonal: '(Diagonal|Dg[.]?)', carrera: '(Avenida |Av[.]? )?(Carrera|Cra[.]?|Kr[.]?)', transversal: '(Transversal|Tv[.]?)', avenida: '(Avenida|Av[.]?)' };
const reVia = v => `^${T[v.tipo] || T.calle} 0*${parseInt(v.numero)}${v.letra ? ' ?' + v.letra : '( ?[A-H])?( ?Bis)?'}${v.norte ? ' ?(Norte|N)' : '( ?(Norte|N|Oeste|Sur))?'}$`;
const bb = '(3.30,-76.60,3.52,-76.45)';
let overpass = '[out:json];out;';
if (clas.vias.length === 2 && clas.vias.every(v => v.numero)) {
  overpass = `[out:json][timeout:12];way["highway"]["name"~"${reVia(clas.vias[0])}",i]${bb}->.a;way["highway"]["name"~"${reVia(clas.vias[1])}",i]${bb}->.b;node(w.a)(w.b);out;`;
}
const lugarQ = clas.lugar ? `${clas.lugar}, Cali, Valle del Cauca` : 'Cali, Valle del Cauca';
return [{ json: { ...prev, clas, overpass, lugarQ, tieneVias: overpass.length > 20 } }];

const prev = $('Fusionar IA').first().json;
const { p, clas } = prev;
const ov = $('Buscar cruce (Overpass)').first().json;
const nomRaw = $('Buscar lugar (Nominatim)').all().map(i => i.json);
const dist = (a, b) => { const R = 6371000, r = x => x * Math.PI / 180; const h = Math.sin(r(b.lat - a.lat) / 2) ** 2 + Math.cos(r(a.lat)) * Math.cos(r(b.lat)) * Math.sin(r(b.lon - a.lon) / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };
const locales = (p.local.candidatos || []).filter(c => c && c.lat);
const est = locales[0] || { lat: 3.43, lon: -76.52 };
const nombreVia = v => `${v.tipo[0].toUpperCase() + v.tipo.slice(1)} ${v.numero}${v.letra || ''}${v.norte ? ' Norte' : ''}`;
let ubic = null;
// 1) Cruce exacto en OpenStreetMap
const nodes = (ov && Array.isArray(ov.elements) ? ov.elements : []).filter(e => e.type === 'node');
if (prev.tieneVias && nodes.length) {
  nodes.sort((x, y) => dist(est, x) - dist(est, y));
  const c = nodes.filter(x => dist(nodes[0], x) < 120);
  ubic = { lat: +(c.reduce((s, x) => s + x.lat, 0) / c.length).toFixed(6), lon: +(c.reduce((s, x) => s + x.lon, 0) / c.length).toFixed(6), label: `${nombreVia(clas.vias[0])} con ${nombreVia(clas.vias[1])}`, fuente: 'OpenStreetMap (n8n)', conf: 'OSM' };
}
// 2) Barrio o intersección conocida calculada por la plataforma
if (!ubic && locales.length && ['alta', 'confirmada'].includes(locales[0].conf)) ubic = { ...locales[0], fuente: 'ColAIre (barrios / semáforos)' };
// 3) Lugar nombrado, buscado en Nominatim
if (!ubic && clas.lugar) {
  const lista = nomRaw.flatMap(x => Array.isArray(x) ? x : (x.lat ? [x] : (Array.isArray(x.data) ? x.data : [])));
  const r = lista.find(x => +x.lat > 3.30 && +x.lat < 3.52 && +x.lon > -76.60 && +x.lon < -76.45);
  if (r) ubic = { lat: +(+r.lat).toFixed(6), lon: +(+r.lon).toFixed(6), label: String(r.display_name || clas.lugar).split(',').slice(0, 2).join(','), fuente: 'Nominatim (n8n)', conf: 'OSM' };
}
// 4) Lo que haya estimado la plataforma
if (!ubic && locales.length) ubic = { ...locales[0], fuente: 'ColAIre (estimación local)' };
return [{ json: { ...prev, ubic } }];

const d = $input.first().json;
const { p, clas, ubic, config } = d;
const RUTEO = { atrapados: ['bomberos','defensacivil','cruzroja','salud','riesgo'], heridos: ['salud','cruzroja','bomberos','riesgo'], colapso: ['bomberos','defensacivil','riesgo'],
  estructura: ['riesgo','bomberos'], incendio: ['bomberos','riesgo','policia'], gas: ['bomberos','riesgo'], electrico: ['bomberos','riesgo'], necesidades: ['riesgo','cruzroja','alcaldia'], via: ['movilidad','policia'], info: ['riesgo'] };
let roles = [];
if (clas.tipo === 'emergencia' || clas.tipo === 'info') {
  roles = [...(RUTEO[clas.categoria] || ['riesgo'])];
  if (clas.urgencia === 'rojo') roles.push('salud','riesgo','alcaldia','gobernacion');
  if (clas.urgencia === 'naranja') roles.push('riesgo','alcaldia');
} else if (clas.tipo === 'ayuda') {
  roles = clas.personal ? ['riesgo','defensacivil','cruzroja','alcaldia'] : ['riesgo','cruzroja','alcaldia','gobernacion'];
  if (clas.items.some(i => ['Personal de salud','Apoyo psicológico','Insumos médicos'].includes(i))) roles.push('salud');
} else if (clas.tipo === 'oferta') roles = ['riesgo','cruzroja'];
roles = [...new Set(roles)];
if (!ubic) roles = [];
const NOMBRE = { salud: 'Sec. Salud', bomberos: 'Bomberos', riesgo: 'Gestión del Riesgo', alcaldia: 'Alcaldía', gobernacion: 'Gobernación', cruzroja: 'Cruz Roja', defensacivil: 'Defensa Civil', movilidad: 'Sec. Movilidad', policia: 'Policía' };
const ICON = { rojo: '🔴 URGENCIA CRÍTICA', naranja: '🟠 URGENCIA ALTA', amarillo: '🟡 URGENCIA MEDIA', azul: '🔵 INFORMATIVO', ninguna: '⚪' };
const CAT = { atrapados: 'Personas atrapadas', heridos: 'Personas heridas', colapso: 'Colapso de edificación', estructura: 'Daño estructural', incendio: 'Incendio / explosión', gas: 'Fuga de gas', electrico: 'Riesgo eléctrico', necesidades: 'Necesidades básicas', via: 'Vía bloqueada', info: 'Información' };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hora = new Date(p.ts).toLocaleString('es-CO', { timeZone: 'America/Bogota', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false });
let titulo = clas.tipo === 'ayuda' ? (clas.personal ? '🙋 SE NECESITA PERSONAL' : '📦 SE NECESITAN INSUMOS') : clas.tipo === 'oferta' ? '🤝 OFRECIMIENTO DE AYUDA' : `${ICON[clas.urgencia]}${clas.categoria ? ' · ' + (CAT[clas.categoria] || clas.categoria) : ''}`;
const texto = [`<b>${esc(titulo)}</b>`, clas.items.length ? `🧾 ${esc(clas.items.join(', '))}` : null,
  ubic ? `📍 ${esc(ubic.label)}` : '📍 Sin ubicación', `🕒 ${esc(hora)}`, `💬 «${esc(p.texto)}»`, `👤 ${esc(p.nombre)}`,
  ubic ? `🗺 https://maps.google.com/?q=${ubic.lat},${ubic.lon}` : null, `🏛 Para: ${esc(roles.map(r => NOMBRE[r] || r).join(', '))}`, '— ColAIre · Cali Resiliente'].filter(Boolean).join('\n');
// Un mensaje por grupo de Telegram configurado (sin repetir grupos)
const chats = new Set(); const C = (config.TELEGRAM_CHATS || {});
if (C.default) chats.add(String(C.default));
for (const r of roles) if (C[r]) chats.add(String(C[r]));
const telegram = config.TELEGRAM_BOT_TOKEN && clas.tipo !== 'charla' && roles.length ? [...chats].map(chat_id => ({ chat_id, text: texto })) : [];
const respuesta = { ok: true, motor: 'n8n', modelo: clas.fuenteIA === 'gemini' ? config.GEMINI_MODEL : 'reglas locales', errorIA: clas.errorIA || null,
  tipo: clas.tipo, urgencia: clas.urgencia, categoria: clas.categoria, items: clas.items, personal: clas.personal, resumen: clas.resumen, lugar: clas.lugar,
  ubic, notificados: roles, telegram: { enviados: telegram.length }, ms: Date.now() - d.t0 };
return [{ json: { respuesta, telegram, token: config.TELEGRAM_BOT_TOKEN } }];
